import zipfile
import re
import xml.etree.ElementTree as ET

NS = "{http://schemas.openxmlformats.org/spreadsheetml/2006/main}"
REL = "{http://schemas.openxmlformats.org/officeDocument/2006/relationships}"

path = "budget.xlsx"
with zipfile.ZipFile(path) as z:
    names = z.namelist()
    print("FILES IN ARCHIVE:")
    for n in names:
        print(" ", n)

    def read(name):
        return z.read(name).decode("utf-8", errors="replace")

    # Map sheet names to sheet XML files via workbook.xml + rels
    wb = ET.fromstring(read("xl/workbook.xml"))
    sheets = []
    for sh in wb.iter(NS + "sheet"):
        sheets.append((sh.get("name"), sh.get(REL + "id")))
    print("\nSHEET NAMES:", [s[0] for s in sheets])

    rels = ET.fromstring(read("xl/_rels/workbook.xml.rels"))
    rid_to_target = {}
    for rel in rels:
        rid_to_target[rel.get("Id")] = rel.get("Target")

    # Shared strings
    shared = []
    if "xl/sharedStrings.xml" in names:
        sst = ET.fromstring(read("xl/sharedStrings.xml"))
        for si in sst.iter(NS + "si"):
            parts = [t.text or "" for t in si.iter(NS + "t")]
            shared.append("".join(parts))

    def col_letter_to_idx(ref):
        m = re.match(r"([A-Z]+)(\d+)", ref)
        letters = m.group(1)
        idx = 0
        for ch in letters:
            idx = idx * 26 + (ord(ch) - ord("A") + 1)
        return idx - 1  # 0-based

    for name, rid in sheets:
        target = rid_to_target.get(rid)
        if target.startswith("/"):
            target = target.lstrip("/")
        else:
            target = "xl/" + target
        print(f"\n=== SHEET: {name} ({target}) ===")
        root = ET.fromstring(read(target))
        sheet_data = root.find(NS + "sheetData")
        if sheet_data is None:
            print("  (empty sheet)")
            continue
        rows = {}
        max_c = 0
        for row in sheet_data.iter(NS + "row"):
            r = int(row.get("r"))
            cells = {}
            for c in row.iter(NS + "c"):
                ref = c.get("r")
                if not ref:
                    continue
                ci = col_letter_to_idx(ref)
                t = c.get("t")
                v = c.find(NS + "v")
                isel = c.find(NS + "is")
                if t == "inlineStr" and isel is not None:
                    val = "".join(x.text or "" for x in isel.iter(NS + "t"))
                elif t == "s" and v is not None:
                    val = shared[int(v.text)]
                elif v is not None:
                    val = v.text
                else:
                    val = ""
                if c.find(NS + "f") is not None:
                    f = c.find(NS + "f").text or ""
                    cells[ci] = (val, f"FORMULA:{f}")
                else:
                    cells[ci] = (val, "")
                max_c = max(max_c, ci)
            rows[r] = cells
        for r in sorted(rows):
            line = []
            for ci in range(max_c + 1):
                if ci in rows[r]:
                    val, note = rows[r][ci]
                    s = f"{val}" if val is not None else ""
                    if note:
                        s += f" [{note}]"
                else:
                    s = ""
                line.append(s)
            print(f"r{r}: " + " | ".join(line))

